    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB0RC_1RC1LB_0LD1RA_1LB1RD : NeverQuasiHaltsTr tm_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
Proof.
  eapply (boardN_neverqhtr tm_1RB0RC_1RC1LB_0LD1RA_1LB1RD pins_1RB0RC_1RC1LB_0LD1RA_1LB1RD FAM 1
                           iarm_1RB0RC_1RC1LB_0LD1RA_1LB1RD 0 1
                           farm_1RB0RC_1RC1LB_0LD1RA_1LB1RD 1 1
                           fm1_1RB0RC_1RC1LB_0LD1RA_1LB1RD fm2_1RB0RC_1RC1LB_0LD1RA_1LB1RD 0
                           nrules vsegs_1RB0RC_1RC1LB_0LD1RA_1LB1RD vis_1RB0RC_1RC1LB_0LD1RA_1LB1RD
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact iarm_lhs_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact iarm_rhs_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - lia.
  - lia.
  - exact farm_reach_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact farm_lhs_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact farm_rhs_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact nrules_sound_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact vis_ok_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
  - exact bootl_1RB0RC_1RC1LB_0LD1RA_1LB1RD.
Qed.

